import java.util.*;

class Solution {
  public List<String> wordBreak(String s, List<String> wordDict) {
    return build(s, 0, new HashSet<>(wordDict), new HashMap<>());
  }

  private List<String> build(String s, int start, Set<String> dict, Map<Integer, List<String>> memo) {
    if (memo.containsKey(start)) return memo.get(start);
    List<String> res = new ArrayList<>();
    if (start == s.length()) res.add("");
    for (int end = start + 1; end <= s.length(); end++) {
      String word = s.substring(start, end);
      if (!dict.contains(word)) continue;
      for (String rest : build(s, end, dict, memo)) res.add(rest.isEmpty() ? word : word + " " + rest);
    }
    memo.put(start, res);
    return res;
  }
}
